/**
 * Guard `src/site/data/lights.json` — the only thing `/the-lights/` reads.
 *
 * `bake-lights.mjs` asserts before it writes, but the artifact is committed and
 * can be hand-edited, go stale against the census, or be regenerated by a
 * future change to the classifier. This re-checks the promises rather than the
 * code that makes them, so it stays honest if the implementation changes:
 *
 * - the counts still match a fresh pass over the census;
 * - the arithmetic is internally consistent;
 * - a point carries nothing but two numbers and a boolean — no name, no id, no
 *   address can hide in the payload if there is no string in it;
 * - **no published point sits on a real premises.** This is the privacy rule
 *   itself, tested directly: the census carries coordinates to centimetre
 *   accuracy, and an undisplaced dark point names the business to anyone with
 *   a map (docs/adr/0005).
 *
 * Run: `node tools/check/check-lights-data.mjs`
 */
import { existsSync, readFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { censusClass, TRADING } from "../pipeline/census-class.mjs";

const projectRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  "..",
  "..",
);

const lightsPath = path.join(projectRoot, "src/site/data/lights.json");
const businessesPath = path.join(projectRoot, "src/site/data/businesses.json");
const removalsPath = path.join(projectRoot, "research/pipeline/removals.json");

if (!existsSync(lightsPath)) {
  console.log(
    "Lights data: not baked yet — run `node tools/pipeline/bake-lights.mjs`.",
  );
  process.exit(0);
}

const lights = JSON.parse(readFileSync(lightsPath, "utf8"));
const rows = JSON.parse(readFileSync(businessesPath, "utf8"));
const removals = existsSync(removalsPath)
  ? JSON.parse(readFileSync(removalsPath, "utf8"))
  : [];

const errors = [];

/* --- The census, re-derived. Stale data is wrong data with a date on it. --- */

const removalKey = (name, town) =>
  `${String(town).toLowerCase().trim()}|${String(name).toLowerCase().trim()}`;
const removed = new Set(
  removals.map((entry) => removalKey(entry.name, entry.town)),
);
const isLit = (row) =>
  row.websiteStatus === "HTTPS website" || row.websiteStatus === "HTTP website";
const isMapped = (row) =>
  typeof row.lat === "number" && typeof row.lon === "number";

const trading = rows
  .filter((row) => censusClass(row) === TRADING)
  .filter((row) => !removed.has(removalKey(row.name, row.town)));
const mapped = trading.filter(isMapped);

const expected = {
  mapped: mapped.length,
  mappedLit: mapped.filter(isLit).length,
  mappedDark: mapped.filter((row) => !isLit(row)).length,
  trading: trading.length,
  tradingLit: trading.filter(isLit).length,
  tradingDark: trading.filter((row) => !isLit(row)).length,
};

for (const [key, value] of Object.entries(expected)) {
  if (lights[key] !== value) {
    errors.push(
      `lights.json ${key} is ${lights[key]}, census says ${value} — rebake`,
    );
  }
}

/* --- Arithmetic, pinned rather than eyeballed. --- */

if (lights.mappedLit + lights.mappedDark !== lights.mapped) {
  errors.push("mapped lit + dark does not equal mapped");
}
if (lights.tradingLit + lights.tradingDark !== lights.trading) {
  errors.push("trading lit + dark does not equal trading");
}
if (!Array.isArray(lights.points) || lights.points.length !== lights.mapped) {
  errors.push(
    `${lights.points?.length} points for ${lights.mapped} mapped businesses`,
  );
}
if (lights.points?.filter((point) => point.lit).length !== lights.mappedLit) {
  errors.push("lit points do not match the lit count");
}

/* --- A count without a date is a claim about now (docs/CONTEXT.md). --- */

if (!/^\d{4}-\d{2}-\d{2}$/.test(lights.reviewedOn ?? "")) {
  errors.push("reviewedOn is missing or is not a full date");
}
if (
  lights.lastCorrectedOn !== null &&
  !/^\d{4}-\d{2}-\d{2}$/.test(lights.lastCorrectedOn ?? "")
) {
  errors.push("lastCorrectedOn must be a full date or null");
}

/* --- Nothing but numbers. No string, no name. --- */

for (const [index, point] of (lights.points ?? []).entries()) {
  const keys = Object.keys(point).sort().join(",");
  if (keys !== "lat,lit,lon") {
    errors.push(`point ${index} carries ${keys} — only lat, lon and lit`);
    continue;
  }
  if (
    !Number.isFinite(point.lat) ||
    !Number.isFinite(point.lon) ||
    typeof point.lit !== "boolean"
  ) {
    errors.push(`point ${index} carries a value that is not a number or boolean`);
  }
}

/* --- The privacy rule itself: no point may sit on a real premises. --- */

/* Each point against *its own* premises, not the nearest of anyone's. A point
 * landing near a neighbouring shop is noise doing its job; a point landing on
 * the business it represents is the leak. The two sets are in the same order
 * because both come from the same filter over the same census. */

const metres = (aLat, aLon, bLat, bLon) =>
  Math.hypot(
    (aLat - bLat) * 111_320,
    (aLon - bLon) * 111_320 * Math.cos((aLat * Math.PI) / 180),
  );

/** Rounding to 4dp can shave or add a few metres after the offset. */
const ROUNDING_SLACK_M = 10;
const floor = lights.displacedMetres?.min;
const ceiling = lights.displacedMetres?.max;

if (!Number.isFinite(floor) || !Number.isFinite(ceiling)) {
  errors.push("displacedMetres must carry a min and a max");
} else {
  let tooNear = 0;
  let tooFar = 0;
  let closest = Infinity;
  (lights.points ?? []).forEach((point, index) => {
    const row = mapped[index];
    if (!row) return;
    const d = metres(point.lat, point.lon, row.lat, row.lon);
    if (d < closest) closest = d;
    if (d < floor - ROUNDING_SLACK_M) tooNear += 1;
    if (d > ceiling + ROUNDING_SLACK_M) tooFar += 1;
  });
  if (tooNear) {
    errors.push(
      `${tooNear} points sit closer than ${floor}m to their own premises ` +
        `(nearest ${closest.toFixed(1)}m) — a point at its true position ` +
        "names the business",
    );
  }
  if (tooFar) {
    errors.push(
      `${tooFar} points sit further than ${ceiling}m from their own premises ` +
        "— the map would be wrong about the town, not merely imprecise",
    );
  }
}

/* --- Darkness may only be drawn where it was evidenced (ADR 0004). --- */

const unevidenced = mapped.filter((row) => !isLit(row) && !row.verification);
if (unevidenced.length) {
  errors.push(
    `${unevidenced.length} dark mapped businesses have no verification object`,
  );
}

if (errors.length) {
  console.error("Lights data check failed:");
  for (const error of errors) console.error(`  - ${error}`);
  process.exit(1);
}

console.log(
  `Lights data: ${lights.mapped} mapped (${lights.mappedLit} lit, ` +
    `${lights.mappedDark} dark), reviewed ${lights.reviewedOn}, ` +
    `every point displaced from its premises.`,
);
